local({
  items <- cbind(SDQ3, SDQ6, SDQ9, SDQ12, SDQ15, SDQ18, SDQ21, SDQ24, SDQ27, SDQ30)
  answered <- rowSums(items >= 1 & items <= 4 & items == round(items), na.rm = TRUE)
  if_else(answered >= 5, as.numeric(SDQ_general), NA_real_)
})

local({
  items <- cbind(SDQ1, SDQ4, SDQ7, SDQ10, SDQ13, SDQ16, SDQ19, SDQ22, SDQ25, SDQ28)
  answered <- rowSums(items >= 1 & items <= 4 & items == round(items), na.rm = TRUE)
  if_else(answered >= 5, as.numeric(SDQ_social), NA_real_)
})
